  min-height: 60vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  background: linear-gradient(rgba(13, 13, 13, 0.7), rgba(13, 13, 13, 0.9)), url('https://placehold.co/1920x1080/1a1a1a/333333?text=Hero+Image') center/cover;
  padding: 2rem 1.5rem;
}

.hero-content {
  max-width: 600px;
}

.hero-content h1 {
  font-size: 3rem;
  margin-bottom: 1rem;
  line-height: 1.2;
}

.hero-content p {
  font-size: 1.2rem;
  color: var(--text-secondary);
  margin-bottom: 2rem;
}

/* Buttons */
.button {
  display: inline-block;
  background-color: var(--surface-alt);
  color: var(--text-primary);
  border: 1px solid var(--border-color);
  padding: 0.75rem 1.5rem;
  font-size: 1rem;
  cursor: pointer;
  text-align: center;
  border-radius: 4px;
  transition: background-color 0.2s;
}

.button:hover {
  background-color: var(--border-color);
  text-decoration: none;
}

.primary-button {
  background-color: var(--accent-color);
  color: var(--bg-color);
  border: none;
  font-weight: bold;
}

.primary-button:hover {
  background-color: var(--accent-hover);
}

/* Product Grid */
.section h2 {
  font-size: 2rem;
  margin-bottom: 2rem;
  text-align: center;
}

.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 2rem;
}

.product-card {
  background-color: var(--surface-color);
  border-radius: 8px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.product-card img {
  width: 100%;
  aspect-ratio: 4/5;
  object-fit: cover;
}

.product-info {
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}

.product-title {
  font-size: 1.2rem;
  margin-bottom: 0.5rem;
}

.product-price {
  font-size: 1.1rem;
  color: var(--text-secondary);
  margin-bottom: 1.5rem;
}

.product-price ins {
  color: var(--text-primary);
  text-decoration: none;
  font-weight: bold;
  margin-right: 0.5rem;
}

.product-price del {
  font-size: 0.9em;
}

.add-to-cart {
  margin-top: auto;
  width: 100%;
}

/* Editorial Grid */
.editorial-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 2rem;
}

.editorial-card {
  background-color: var(--surface-color);
