document.addEventListener('DOMContentLoaded', () => {
  // Update current year in footer
  document.getElementById('current-year').textContent = new Date().getFullYear();

  // Cart state
  let cartCount = 0;
  const cartBtn = document.getElementById('cart-btn');
  const cartCountEl = document.getElementById('cart-count');
  const liveRegion = document.getElementById('live-region');
  const addToCartButtons = document.querySelectorAll('.add-to-cart');

  addToCartButtons.forEach(button => {
    button.addEventListener('click', (e) => {
      const productName = e.target.getAttribute('data-product');

      // Update cart count
      cartCount++;
      cartCountEl.textContent = cartCount;

      // Update cart button accessible name
      const itemsText = cartCount === 1 ? 'item' : 'items';
      cartBtn.setAttribute('aria-label', `Shopping Cart with ${cartCount} ${itemsText}`);

      // Announce to screen readers
      liveRegion.textContent = `${productName} added to cart.`;

      // Clear live region after a delay so subsequent identical announcements are still read
      setTimeout(() => {
        liveRegion.textContent = '';
      }, 3000);
    });
  });

  // Newsletter form submission
  const newsletterForm = document.getElementById('newsletter-form');
  if (newsletterForm) {
    newsletterForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const emailInput = document.getElementById('newsletter-email');

      // Simulate submission
      liveRegion.textContent = `Successfully subscribed with email ${emailInput.value}.`;
      emailInput.value = '';

      // Optional: Add a visual success message
      const hint = document.getElementById('newsletter-hint');
      hint.textContent = 'Thank you for subscribing!';
      hint.style.color = 'var(--text-primary)';

      setTimeout(() => {
        liveRegion.textContent = '';
      }, 3000);
    });
  }
});
