/* Custom properties for dark mode */
:root {
  --bg-color: #0d0d0d;
  --surface-color: #1a1a1a;
  --surface-alt: #242424;
  --text-primary: #f0f0f0;
  --text-secondary: #a0a0a0;
  --accent-color: #ffffff;
  --accent-hover: #cccccc;
  --error-color: #ff8a8a;
  --focus-ring: #ffffff;
  --border-color: #333333;
}

/* Base resets & typography */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-primary);
  line-height: 1.6;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

ul {
  list-style: none;
}

a {
  color: var(--text-primary);
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

/* Accessibility utilities */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

.skip-link {
  position: absolute;
  top: -40px;
  left: 0;
  background: var(--accent-color);
  color: var(--bg-color);
  padding: 0.5rem 1rem;
  z-index: 100;
  transition: top 0.2s ease;
  font-weight: bold;
}

.skip-link:focus {
  top: 0;
}

/* Focus indicators */
*:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 2px;
}

/* Layout containers */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

.section {
  padding: 4rem 1.5rem;
  max-width: 1200px;
  margin: 0 auto;
}

.alt-bg {
  background-color: var(--surface-color);
  max-width: 100%;
  padding-left: max(1.5rem, calc((100% - 1200px) / 2));
  padding-right: max(1.5rem, calc((100% - 1200px) / 2));
}

/* Header */
.site-header {
  background-color: var(--bg-color);
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 0;
  z-index: 10;
}

.header-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 1rem 1.5rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
}

.logo {
  font-size: 1.5rem;
  font-weight: bold;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}
.logo:hover {
  text-decoration: none;
}

.main-nav ul {
  display: flex;
  gap: 1.5rem;
}

.main-nav a {
  font-weight: 500;
  font-size: 0.95rem;
}

#cart-btn {
  background: none;
  border: 1px solid var(--border-color);
  color: var(--text-primary);
  padding: 0.5rem 1rem;
  cursor: pointer;
  font-size: 0.95rem;
  border-radius: 4px;
}

#cart-btn:hover {
  background-color: var(--surface-color);
}

/* Hero */
.hero {
  min-height: 60vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  background: linear-gradient(rgba(13, 13, 13, 0.7), rgba(13, 13, 13, 0.9)), url('https://placehold.co/1920x1080/1a1a1a/333333?text=Hero+Image') center/cover;
  padding: 2rem 1.5rem;
}

.hero-content {
  max-width: 600px;
}

