.editorial-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 2rem;
}

.editorial-card {
  background-color: var(--surface-color);
  border-radius: 8px;
  overflow: hidden;
}

.editorial-card img {
  width: 100%;
  aspect-ratio: 3/2;
