}

.editorial-info {
  padding: 1.5rem;
}

.editorial-info h3 {
  font-size: 1.5rem;
  margin-bottom: 0.5rem;
}

.editorial-info p {
  color: var(--text-secondary);
  margin-bottom: 1rem;
}

.read-more {
  font-weight: bold;
  display: inline-flex;
  align-items: center;
}
.read-more::after {
  content: "→";
  margin-left: 0.5rem;
