  gap: 3rem;
  margin-bottom: 3rem;
}

.footer-col h3 {
  margin-bottom: 1.5rem;
  font-size: 1.2rem;
}

.footer-col p {
  color: var(--text-secondary);
}

.footer-col ul {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.footer-col a {
  color: var(--text-secondary);
}

.footer-col a:hover {
  color: var(--text-primary);
